import numpy as npfrom math import log, atan# Auxiliary function: Convert a frequency in linear scale to Mel scale.def _linear_to_mel(freq: float) -> float:    return (1127 * log(1 + freq / 700))# Auxiliary function: Convert a frequency in linear scale to Bark scale.def _linear_to_bark(freq: float) -> float:    norm_freq_1 = 0.00076 * freq    norm_freq_2 = freq / 7500    return (13 * atan(norm_freq_1) + 3.5 * atan(norm_freq_2**2))def spectral_filter_bank(sampling_rate: float,                         num_bins: int, num_bands: int,                         min_frequency: float, max_frequency: float,                         spacing: str, shape: str) -> np.ndarray:    """    Create a matrix containing a spectral filter bank.    Parameters    ----------        sampling_rate : float        The sampling rate of the audio signal, in Hz.            num_bins : int        The number of input spectral bins.            num_bands : int        The number of output spectral bands.            min_frequency : float        The minimal frequency to consider, in Hz: between 0 and sampling_rate/2.            max_frequency : float        The maximal frequency to condier, in Hz: between 0 and sampling_rate/2.        May be negative, in which case it is trated as an offset from the nyquist frequency sampling_rate/2.            spacing : str        The spacing between bands: either 'linear', 'mel' or 'bark'.    shape : str        The shape of the filters: either 'rectangular' or 'triangular'.    Returns    -------        filters_mat : np.ndarray        A matrix of shape (num_bands, num_bins) containing the filter coefficients.    """        # Check the input parameters.    if sampling_rate <= 0:        raise('Invalid sampling rate %f - must be positive.' % sampling_rate)    if num_bins <= 0:        raise('Invalid number of spectral bins %d - must be positive.' % num_bins)    if num_bands <= 0:        raise('Invalid number of spectral bands %d - must be positive.' % num_bands)    if shape.lower().startswith('rect'):        rect_filter = True    elif shape.lower().startswith('tri'):        rect_filter = False    else:        raise('Invalid shape option "%s".' % shape)        # Check the validity of the frequency range.    nyquist_freq = 0.5 * sampling_rate    if min_frequency < 0 or min_frequency >= nyquist_freq:        raise('Invalid minimal frequency %f (must be between 0 and %f).' % (min_frequency, nyquist_freq))    if max_frequency < 0:        max_frequency += nyquist_freq    if max_frequency <= min_frequency or max_frequency > nyquist_freq:        raise('Invalid maximal frequency %f (must be between %f and %f).' % (max_frequency, min_frequency, nyquist_freq))    # Compute the width of the frequency band that each frequency bin represents, and determine the difference    # between each two central frequencies for the filters.    bin_width = nyquist_freq / num_bins    num_intervals = num_bands if rect_filter else num_bands + 1    bin_freqs = [0] * num_bins    base_freq = 0    delta_freq = 0    if (spacing.lower() == 'linear'):        # The frequency bands are equally and linearly spaced.        base_freq = min_frequency        delta_freq = (max_frequency - min_frequency) / num_intervals        # Compute the frequency that each spectral bin corresponds to.        for bin_ind in range(num_bins):            bin_freqs[bin_ind] = bin_ind * bin_width    elif (spacing.lower() == 'mel'):        # The frequency bands are equally spaced along the Mel frequency scale.        min_mel_freq = _linear_to_mel(min_frequency)        max_mel_freq = _linear_to_mel(max_frequency)        base_freq = min_mel_freq;        delta_freq = (max_mel_freq - min_mel_freq) / num_intervals        # Compute the Mel frequency that each spectral bin corresponds to.        for bin_ind in range(num_bins):            bin_freqs[bin_ind] = _linear_to_mel(bin_ind * bin_width)    elif (spacing.lower() == 'bark'):        # The frequency bands are equally spaced along the Bark frequency scale.        min_bark_freq = _linear_to_bark(min_frequency)        max_bark_freq = _linear_to_bark(max_frequency)        base_freq = min_bark_freq;        delta_freq = (max_bark_freq - min_bark_freq) / num_intervals;        # Compute the Bark frequency that each spectral bin corresponds to.        for bin_ind in range(num_bins):            bin_freqs[bin_ind] = _linear_to_bark(bin_ind * bin_width)    else:        raise('Invalid spacing option "%s".' % spacing)    # Compute the band filters.    filters_mat = np.zeros((num_bands, num_bins))    if rect_filter:        # Go over all frequency bands and create the rectangular filters.        for band_ind in range(num_bands):            # Each filter spans the frequency range [band_ind * delta_freq, (band_ind + 1) * delta_freq].            min_band_freq = base_freq + band_ind * delta_freq            max_band_freq = min_band_freq + delta_freq            # Compute the filter coefficients.            for bin_ind in range(num_bins):                bin_freq = bin_freqs[bin_ind]                if (bin_freq >= min_band_freq) and (bin_freq < max_band_freq):                    filters_mat[band_ind, bin_ind] = 1            else:        # Go over all frequency bands and create the triangular filters.        for band_ind in range(num_bands):            # Each filter spans the frequency range [band_ind * delta_freq, (band_ind + 2) * delta_freq].            min_band_freq = base_freq + band_ind * delta_freq            central_band_freq = min_band_freq + delta_freq            max_band_freq = central_band_freq + delta_freq            # Compute the filter coefficients.            for bin_ind in range(num_bins):                bin_freq = bin_freqs[bin_ind]                if (bin_freq > min_band_freq) and (bin_freq < max_band_freq):                    if (bin_freq <= central_band_freq):                        # The filter goes up from 0 to 1 between its minimal frequency and its central frequency.                        coeff = (bin_freq - min_band_freq) / (central_band_freq - min_band_freq)                    else:                        # The filter goes down from 1 to 0 between its central frequency and its maximal frequency.                        coeff = (max_band_freq - bin_freq) / (max_band_freq - central_band_freq)                    filters_mat[band_ind, bin_ind] = coeff    return filters_mat